// The Webhook node nests the POSTed JSON under `body` — unwrap it so the
// HTTP node downstream forwards the disclosure payload itself rather than
// the request envelope (headers/query/params). Falls back to the item as-is
// so manual "Execute workflow" runs with pinned data still work.
const p = $input.item.json.body ?? $input.item.json;
return {
  json: {
    ...p,
    routedVia: "n8n mock workflow (no real Sahyog endpoint exists)"
  }
};
